const TONE={Active:'ok',Accepted:'ok',Approved:'ok',Delivered:'ok',Completed:'ok',Verified:'ok',Open:'ok',Used:'ok',Resolved:'ok',Passed:'ok',Connected:'ok',Pilot:'ok',Pending:'warn',Invited:'warn','2FA pending':'warn','Awaiting approval':'warn',Planned:'warn',Conflict:'warn','Update required':'warn','Wipe pending':'warn',Queued:'warn',Unread:'warn',Disabled:'bad',Rejected:'bad',Revoked:'bad',Failed:'bad',Expired:'bad',Locked:'bad','Not connected':'bad'};

let on=false;/* true while a platform page is on screen */
let db=load(),page='health',filters={search:'',role:'all',status:'all',actor:'all',school:'sch1'},pendingLogin=null;
function load(){try{return JSON.parse(localStorage.getItem(KEY))||structuredClone(seed)}catch{return structuredClone(seed)}}
const save=()=>localStorage.setItem(KEY,JSON.stringify(db));
const when=t=>t?new Date(t).toLocaleString('en-GB',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'—',dshort=t=>t?new Date(t).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}):'—';
const byId=id=>db.users.find(x=>x.id===id),person=id=>byId(id)?.name||db.guardians.find(x=>x.id===id)?.name||'—',student=id=>db.students.find(x=>x.id===id),school=id=>db.schools.find(x=>x.id===id)?.name||'—';
const roleName=k=>ROLES.find(r=>r[0]===k)?.[1]||k,permName=k=>PERMS.find(p=>p[0]===k)?.[1]||k,actor=()=>byId(db.actor);
const cfg=key=>{const c=db.config.find(x=>x.key===key);return c.versions[c.versions.length-1].value};
const needsMfa=u=>[...u.roles,...(u.requestedRoles||[])].some(r=>PRIVILEGED.includes(r));
function userStatus(u){if(u.disabled)return'Disabled';if(!u.steps.accepted)return'Invited';if(needsMfa(u)&&!u.steps.mfa)return'2FA pending';if(!u.steps.approved)return'Awaiting approval';return'Active'}
const nextStep=u=>u.disabled?null:!u.steps.accepted?'Accept invite':needsMfa(u)&&!u.steps.mfa?'Set up 2FA':null;
const vnum=v=>v.split('.').map(Number).reduce((a,n)=>a*1000+n,0),outdated=s=>s.status==='Active'&&db.minVersions[s.app]&&vnum(s.version)<vnum(db.minVersions[s.app]);
const can=(u,p)=>!!u&&!u.disabled&&u.roles.some(r=>(db.matrix[r]||[]).includes(p));
const RULES={admin:u=>can(u,'manage_users'),leader:u=>can(u,'manage_users')||u.roles.some(r=>['principal','vp'].includes(r)),guardians:u=>can(u,'manage_users')||can(u,'approve_admissions'),approver:u=>can(u,'manage_users')||u.roles.includes('principal')};
function guard(rule,fn){const u=actor();if(!u||!RULES[rule](u)){toast(`${u?.name||'This user'} isn't allowed to do that. Use “Acting as” to switch user.`);return}fn()}
function audit(action,entity,before='',after='',reason=''){const a=actor();db.audit.unshift({id:uid('au'),at:iso(),actor:a?.id,role:a?a.roles.map(roleName).join(', '):'',action,entity,before:String(before),after:String(after),reason,device:'Web · this browser',ip:'192.168.1.24'});save()}
function request(type,summary,payload,reason){db.approvals.unshift({id:uid('ap'),type,summary,payload,by:db.actor,at:iso(),reason,status:'Pending'});audit('approval.request',summary,'','Pending',reason);render()}
function applyApproval(a){const p=a.payload;
  if(a.type==='roles'){const u=byId(p.user);u.roles=p.roles;u.requestedRoles=[];u.steps.approved=true}
  else if(a.type==='perm'){const list=db.matrix[p.role];db.matrix[p.role]=p.allow?[...new Set([...list,p.perm])]:list.filter(x=>x!==p.perm)}
  else if(a.type==='reactivate'){byId(p.user).disabled=false}
  else if(a.type==='reopen'){for(const y of db.years){const q=y.seqs.find(q=>q.id===p.seq);if(q)q.status='Open'}}}
function tick(){db.codes.forEach(c=>{if(c.status==='Active'&&new Date(c.expires)<new Date())c.status='Expired'})}

function toast(t){const x=$('#toast');x.textContent=t;x.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>x.classList.remove('show'),3200)}
function modal(title,body,onSubmit,submit='Save'){$('#modalTitle').textContent=title;$('#modalForm').innerHTML=body+(onSubmit?`<div class="form-actions"><button class="mini-btn" type="button" data-close>Cancel</button><button class="mini-btn primary">${submit}</button></div>`:`<div class="form-actions"><button class="mini-btn primary" type="button" data-close>Done</button></div>`);$('#modalLayer').classList.add('open');$('#modalForm').onsubmit=e=>{e.preventDefault();if(onSubmit&&onSubmit(Object.fromEntries(new FormData(e.target)))!==false)close()}}
function close(){$('#modalLayer').classList.remove('open')}
const input=(n,l,v='',type='text',r=false)=>`<label class="form-label">${l}${r?' *':''}<input name="${n}" type="${type}" value="${esc(v)}" ${r?'required':''}></label>`;
const choose=(n,l,v,items)=>`<label class="form-label">${l}<select name="${n}">${items.map(([k,t])=>`<option value="${esc(k)}" ${k===v?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;
const area=(n,l,v='',r=false)=>`<label class="form-label">${l}${r?' *':''}<textarea name="${n}" rows="3" ${r?'required':''}>${esc(v)}</textarea></label>`;
const checks=(n,items,sel=[])=>`<div class="check-grid">${items.map(([k,t])=>`<label><input type="checkbox" name="${n}" value="${k}" ${sel.includes(k)?'checked':''}> ${esc(t)}</label>`).join('')}</div>`;
const checked=n=>$$(`#modalForm input[name="${n}"]:checked`).map(i=>i.value);
const card=(l,v,s='')=>`<article class="metric"><span>${esc(l)}</span><strong>${v}</strong><small>${esc(s)}</small></article>`;
const badge=v=>`<span class="badge tone-${TONE[v]||'none'}">${esc(v)}</span>`;
const table=(head,rows)=>`<div class="admin-table-wrap"><table class="admin-table"><thead><tr>${head.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td class="no-data" colspan="${head.length}">No matching records.</td></tr>`}</tbody></table></div>`;
